48: /** Attach a browser which was launched and authenticated by the authorized host,
49:  * before the first F04 manifest can exist. Never launch/restart a browser here.
50:  */
51: export async function attachHostedNativeBrowser(scratchRoot: string): Promise<Browser> {
52:   const endpoint = await privateEndpoint(scratchRoot)
53:   try { return await chromium.connectOverCDP(endpoint, { timeout: 30000 }) }
54:   catch { throw new Error("F04_APPROVED_HOST_BROWSER_NOT_CONNECTED") }
55: }
